//! Emoji picker: every fully-qualified Unicode emoji (from the `emojis` crate) with its
//! CLDR English keywords (`data/emoji-keywords.tsv`, regenerated by
//! `scripts/gen-emoji-keywords.py`) and GitHub shortcodes. A shortcode is a keyword, and
//! `:smile` or `:smile:` is an alias that pins 😄; emoji whose shortcode equals the query
//! are returned first, so plain `smile` ranks 😄 above other smiling faces.

use std::collections::HashMap;

use quickhop_core::{Action, Cancel, Item, ItemId, Provider, ProviderError, Query};

/// Provider name.
pub const NAME: &str = "emoji";

const KEYWORDS: &str = include_str!("../data/emoji-keywords.tsv");

/// CLDR keywords by emoji glyph.
fn keywords() -> HashMap<&'static str, Vec<&'static str>> {
    KEYWORDS
        .lines()
        .filter(|line| !line.starts_with('#'))
        .filter_map(|line| line.split_once('\t'))
        .map(|(glyph, words)| (glyph, words.split('|').filter(|w| !w.is_empty()).collect()))
        .collect()
}

fn group_name(group: emojis::Group) -> &'static str {
    match group {
        emojis::Group::SmileysAndEmotion => "Smileys & Emotion",
        emojis::Group::PeopleAndBody => "People & Body",
        emojis::Group::AnimalsAndNature => "Animals & Nature",
        emojis::Group::FoodAndDrink => "Food & Drink",
        emojis::Group::TravelAndPlaces => "Travel & Places",
        emojis::Group::Activities => "Activities",
        emojis::Group::Objects => "Objects",
        emojis::Group::Symbols => "Symbols",
        emojis::Group::Flags => "Flags",
    }
}

/// The emoji list, built once.
pub struct EmojiProvider {
    items: Vec<Item>,
}

impl Default for EmojiProvider {
    fn default() -> Self {
        Self::new()
    }
}

impl EmojiProvider {
    /// Builds the list (about 1900 emoji).
    pub fn new() -> Self {
        let keywords = keywords();
        let items = emojis::iter()
            .map(|emoji| {
                let glyph = emoji.as_str();
                // Variation selectors differ between sources; match without them.
                let words = keywords
                    .get(glyph)
                    .or_else(|| keywords.get(glyph.trim_end_matches('\u{fe0f}')))
                    .cloned()
                    .unwrap_or_default();
                let shortcodes: Vec<&str> = emoji.shortcodes().collect();
                let key: Vec<String> = glyph
                    .chars()
                    .map(|c| format!("{:x}", u32::from(c)))
                    .collect();
                let mut subtitle = group_name(emoji.group()).to_owned();
                if !shortcodes.is_empty() {
                    subtitle = format!(":{}: · {subtitle}", shortcodes.join(": :"));
                }
                Item::new(
                    ItemId::new(NAME, key.join("-")),
                    format!("{glyph} {}", emoji.name()),
                    Action::Copy {
                        text: glyph.to_owned(),
                    },
                )
                .with_subtitle(subtitle)
                .with_keywords(shortcodes.iter().copied().chain(words.iter().copied()))
                .with_aliases(
                    shortcodes
                        .iter()
                        .flat_map(|s| [format!(":{s}:"), format!(":{s}")]),
                )
                .with_icon(glyph)
            })
            .collect();
        Self { items }
    }

    /// Every emoji item.
    pub fn all(&self) -> &[Item] {
        &self.items
    }
}

impl Provider for EmojiProvider {
    fn name(&self) -> &str {
        NAME
    }

    /// Nothing for an empty query: 1900 emoji would bury everything else. Emoji whose
    /// shortcode is the query come first.
    fn items(&self, query: &Query, cancel: &Cancel) -> Result<Vec<Item>, ProviderError> {
        if cancel.is_cancelled() {
            return Err(ProviderError::Cancelled {
                provider: NAME.into(),
            });
        }
        if query.is_empty() {
            return Ok(Vec::new());
        }
        let wanted = format!(":{}:", query.text().to_lowercase().trim_matches(':'));
        let (mut exact, rest): (Vec<Item>, Vec<Item>) = self
            .items
            .iter()
            .cloned()
            .partition(|item| item.aliases.contains(&wanted));
        exact.extend(rest);
        Ok(exact)
    }

    fn has_key(&self, key: &str) -> Result<bool, ProviderError> {
        Ok(self.items.iter().any(|item| item.id.key == key))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn most_emoji_have_cldr_keywords() {
        let provider = EmojiProvider::new();
        let all = provider.all();
        assert!(all.len() > 1500, "{}", all.len());
        let with_keywords = all.iter().filter(|i| !i.keywords.is_empty()).count();
        assert!(
            with_keywords * 100 / all.len() >= 95,
            "{with_keywords} of {}",
            all.len()
        );
    }

    #[test]
    fn shortcodes_are_aliases() {
        let provider = EmojiProvider::new();
        let smile = provider
            .all()
            .iter()
            .find(|i| i.aliases.iter().any(|a| a == ":smile:"))
            .unwrap();
        assert!(smile.aliases.iter().any(|a| a == ":smile"));
        assert_eq!(smile.keywords[0], "smile");
        assert!(smile.title.starts_with('😄'), "{}", smile.title);
        assert!(smile.keywords.iter().any(|k| k == "laugh"));
        assert_eq!(
            smile.default_action(),
            Some(&Action::Copy {
                text: "😄".into()
            })
        );
    }

    #[test]
    fn exact_shortcodes_come_first() {
        let provider = EmojiProvider::new();
        for query in ["smile", ":smile:", "SMILE"] {
            let items = provider.items(&Query::new(query), &Cancel::new()).unwrap();
            assert!(
                items[0].title.starts_with('😄'),
                "{query}: {}",
                items[0].title
            );
            assert_eq!(items.len(), provider.all().len());
        }
    }
}
